insert into public.product_items (product_id, position, child_product_id)
select pk.id, coalesce((select max(position) from public.product_items x where x.product_id = pk.id), 0)
         + row_number() over (partition by pk.id order by c.slug), c.id
  from (values
    ('age-aux-pack-completo-2026', 'age-aux-simulacro-examen-2026'),
    ('age-aux-pack-completo-2026', 'age-aux-simulacro-examen-2024'),
    ('age-adm-pack-completo-2026', 'age-adm-simulacro-examen-2025'),
    ('age-adm-pack-completo-2026', 'age-adm-simulacro-examen-2024'),
    ('jus-auxilio-pack-completo-2026', 'jus-auxilio-simulacro-examen-2026'),
    ('jus-auxilio-pack-completo-2026', 'jus-auxilio-simulacro-examen-2026-casos'),
    ('jus-tramitacion-pack-completo-2026', 'jus-tramitacion-simulacro-examen-2026'),
    ('jus-tramitacion-pack-completo-2026', 'jus-tramitacion-simulacro-examen-2026-casos'),
    ('jus-tramitacion-pack-completo-2026', 'jus-tramitacion-simulacro-examen-2026-ofimatica'),
    ('mossos-pack-complet-2026', 'mossos-simulacre-examen-46-26'),
    ('mossos-pack-complet-2026', 'mossos-simulacre-examen-46-25')
  ) as v(pack, child)
  join public.products pk on pk.slug = v.pack
  join public.products c on c.slug = v.child
 where not exists (select 1 from public.product_items i where i.product_id = pk.id and i.child_product_id = c.id);

