-- Publicar los simulacros réplica si cada parte o cupo tiene sus preguntas publicadas
update public.products p set status = 'published'
 where p.status = 'draft' and p.is_test = false and p.type = 'mock_exam'
   and (p.slug like '%-simulacro-examen-%' or p.slug like 'mossos-simulacre-examen-%')
   and ((p.config->>'kind' = 'sections' and public.mock_sections_ready(p.id))
        or (coalesce(p.config->>'kind', '') <> 'sections' and public.mock_quotas_ready(p.id)));

commit;
